#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, s;
    cin >> n >> s;
    vector<int> c(n), d(s + 1, 1000000000);
    for (int &v : c) cin >> v;
    d[0] = 0;
    for (int i = 1; i <= s; i++)
        for (int v : c)
             if (v <= i) d[i] = min(d[i], d[i - v] + 1);
    cout << (d[s] >= 1000000000 ? -1 : d[s]);
}
